func (c *Component) Start(ctx context.Context) (startErr error) {
	// Validate before inspecting lifecycle state.
	if ctx == nil {
		return errs.WrapInvalid(errs.ErrInvalidConfig, "Component", "Start", "context cannot be nil")
	}
	if err := ctx.Err(); err != nil {
		return errs.WrapInvalid(err, "Component", "Start", "context already cancelled")
	}
	c.lifecycleMu.Lock()
	c.mu.RLock()
	initialized := c.initialized
	c.mu.RUnlock()
	// Check initialization
	if !initialized {
		c.lifecycleMu.Unlock()
		return errs.WrapFatal(errs.ErrInvalidConfig, "Component", "Start", "component not initialized")
	}

	if c.lifecycleUsed {
		c.lifecycleMu.Unlock()
		return errs.WrapFatal(errs.ErrInvalidConfig, "Component", "Start", "component instance already used")
	}

	// Create cancellable context
	parent := ctx
	ctx, cancel := context.WithCancel(ctx)
	startDone := make(chan struct{})
	c.lifecycleUsed = true
	c.cancel = cancel
	c.startDone = startDone
	c.cleanupPending = true
	c.lifecycleMu.Unlock()

	committed := false
	defer func() {
		startErr = c.finishStart(parent, startDone, committed, startErr)
	}()

	// Check context before proceeding
	if err := ctx.Err(); err != nil {
		return errs.Wrap(err, "Component", "Start", "context cancelled")
	}

	// Acquire COMMUNITY_SUMMARIES FIRST (the enhancement worker is the sole
	// WRITER; graph-query opens it read-only for its cache's second watcher). It is
	// created BEFORE COMMUNITY_INDEX deliberately: consumers wait on COMMUNITY_INDEX
	// as the readiness signal, so having the summary bucket already present when
	// COMMUNITY_INDEX becomes observable closes the startup window where a reader
	// could see the partition bucket but not yet the summary bucket. The catalog
	// declares it no-lifecycle (ADR-068): regenerable derived data whose keys are
	// content-addressed, so it never carries reachability-blind eviction.
	summaryBucket, err := graph.EnsureCatalogBucket(ctx, c.natsClient, graph.BucketCommunitySummaries)
	if err != nil {
		startErr := errs.Wrap(err, "Component", "Start", fmt.Sprintf("KV bucket creation: %s", graph.BucketCommunitySummaries))
		if ctx.Err() != nil {
			startErr = errs.Wrap(ctx.Err(), "Component", "Start", "context cancelled during bucket creation")
		}
		return startErr
	}
	c.summaryBucket = summaryBucket

	// COMMUNITY_INDEX bucket (we are the WRITER)
	communityBucket, err := graph.EnsureCatalogBucket(ctx, c.natsClient, graph.BucketCommunityIndex)
	if err != nil {
		startErr := errs.Wrap(err, "Component", "Start", fmt.Sprintf("KV bucket creation: %s", graph.BucketCommunityIndex))
		if ctx.Err() != nil {
			startErr = errs.Wrap(ctx.Err(), "Component", "Start", "context cancelled during bucket creation")
		}
		return startErr
	}
	c.communityBucket = communityBucket

	// Create community storage for the detector
	c.storage = clustering.NewNATSCommunityStorage(communityBucket)

	// Bind the readiness feed BEFORE the detection loop can tick, so the first tick
	// decides against a delivered envelope rather than an artificial unknown. Start
	// never fails on an absent bucket or key: a deployment running clustering without
	// graph-index is a legitimate shape whose readiness is simply unknown, and
	// allow_ungated_reads — not a fabricated envelope — is what covers it.
	if err := c.startStatusWatcher(ctx); err != nil {
		return errs.Wrap(err, "Component", "Start", "readiness status watcher")
	}

	if err := c.waitForDependencies(ctx); err != nil {
		return err
	}

	// Set up query handlers. Contract poison is detected at consume time on
	// the input path (poison-response-scoping D7): every authoritative entity
	// read flows through the latch-wired querier built below, so there is no
	// dedicated ENTITY_STATES contract watcher and no per-write fan-out to
	// clustering.
	if err := c.setupQueryHandlers(ctx); err != nil {
		return errs.Wrap(err, "Component", "Start", "setup query handlers")
	}

	// Create graph provider and detector. The sticky poison latch survives a
	// owner lifetime (only a process restart clears it): a poisoned component keeps
	// its query surface available so it can return the typed reset requirement, but
	// no detector/enhancement/action worker may run against incompatible state.
	c.initProviderAndDetector()
	poisoned := c.graphStatePoison.Load() != nil

	// Anomaly initialization owns its ephemeral structural prerequisites; it has
	// no durable structural bucket or storage dependency. Clear prior-start
	// runtime state first so only this Start's successful initialization can
	// authorize structural computation or review workers.
	c.anomalyOrchestrator = nil
	c.anomalyStorage = nil
	c.similarityFinder = nil
	if !poisoned && c.config.EnableAnomalyDetection {
		if err := c.initAnomalyDetection(ctx); err != nil {
			c.anomalyOrchestrator = nil
			c.anomalyStorage = nil
			c.similarityFinder = nil
			c.logger.Warn("failed to initialize anomaly detection, continuing without it",
				slog.Any("error", err))
		}
	}

	// Start LLM enhancement worker if enabled
	if !poisoned && c.config.EnableLLM {
		if err := c.startEnhancementWorker(ctx); err != nil {
			c.logger.Warn("failed to start enhancement worker, continuing without LLM",
				slog.Any("error", err))
		}
	}

	// Start review worker if enabled (for anomaly approval workflow)
	if !poisoned && c.config.AnomalyConfig.Review.Enabled && c.anomalyStorage != nil {
		if err := c.startReviewWorker(ctx); err != nil {
			c.logger.Warn("failed to start review worker, continuing without anomaly review",
				slog.Any("error", err))
		}
	}

	// Mark as running
	c.mu.Lock()
	c.running = true
	c.startTime = time.Now()
	startTime := c.startTime
	c.mu.Unlock()

	// Start detection loop goroutine
	if !poisoned {
		c.wg.Add(1)
		go c.runDetectionLoop(ctx)
	}
	c.runtimeDone = make(chan struct{})
	go func(done chan struct{}) {
		c.wg.Wait()
		close(done)
	}(c.runtimeDone)
	committed = true

	c.logger.Info("component started",
		slog.String("component", "graph-clustering"),
		slog.Time("start_time", startTime),
		slog.Duration("detection_interval", c.config.DetectionInterval()),
		slog.Bool("enable_llm", c.config.EnableLLM),
		slog.Bool("enable_anomaly_detection", c.config.EnableAnomalyDetection))

	return nil
}

